use vstd::prelude::*;

verus! {

/// Given a vector of complex numbers (real, imag),
/// returns a vector of their imaginary parts,
/// preserving order and length.
fn imag(val: Vec<(f64, f64)>) -> (res: Vec<f64>)
    ensures
        // Output has the same length as the input
        res.len() == val.len(),
    ensures
        // For every valid index i, res[i] is the imaginary part of val[i]
        forall|i: usize| i < val.len() ==> res[i] == val[i].1,
    ensures
        // If the imaginary part is exactly 0.0, then res[i] is 0.0
        forall|i: usize| i < val.len() && val[i].1 == 0.0 ==> res[i] == 0.0,
    ensures
        // If the complex number is non-zero, res[i] equals its imaginary part
        forall|i: usize| i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0)
                    ==> res[i] == val[i].1,
{
    let mut res: Vec<f64> = Vec::new();
    let mut idx: usize = 0;
    while idx < val.len()
        invariant
            idx <= val.len(),
            res.len() == idx,
            forall|j: usize| j < idx ==> res[j] == val[j].1,
        decreases val.len() - idx,
    {
        let imag_part = val[idx].1;
        idx += 1;
        res.push(imag_part);
    }
    res
}

}